		baseZ := g.colZ()
		tileB(qkv, w.Z, c.Inner, c.NEmbd, func(r int) int { return baseZ + r })
		baseA := g.colAlpha()
		tileB(qkv, w.Alpha, c.NHeadV, c.NEmbd, func(r int) int { return baseA + r })
		baseB := g.colBeta()
		tileB(qkv, w.Beta, c.NHeadV, c.NEmbd, func(r int) int { return baseB + r })
